/**
 * Builds the CLI banner. Truecolor terminals get the full-color logo; every
 * other terminal falls back to a cyan silhouette so the banner still renders.
 */
export const buildBundleDropLogo = (): string => {
  const art =
    chalk.level >= 3
      ? BUNDLE_DROP_LOGO_TRUECOLOR
      : chalk.cyanBright(BUNDLE_DROP_LOGO_MONO);

  const title = chalk.bold.cyanBright(
    `${figures.star} React Native Bundle Drop CLI ${figures.star}`,
  );

  return `\n${art}\n\n${title}`;
};
